package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class ShapePolymorphismTest {

    @Test
    fun circleArea() {
        val c = Circle(2.0)
        assertEquals(Math.PI * 4.0, c.area(), 1e-9)
    }

    @Test
    fun rectangleArea() {
        val r = Rectangle(3.0, 4.0)
        assertEquals(12.0, r.area(), 1e-9)
    }

    @Test
    fun triangleArea() {
        val t = Triangle(6.0, 5.0)
        assertEquals(15.0, t.area(), 1e-9)
    }

    @Test
    fun polymorphicListSum() {
        val shapes: List<Shape> = listOf(Circle(1.0), Rectangle(2.0, 3.0), Triangle(4.0, 2.0))
        val total = shapes.sumOf { it.area() }
        assertEquals(Math.PI + 6.0 + 4.0, total, 1e-9)
    }
}

